import pages as PG
from pages import *
from pages import foreword,glance,reading,story,cards,end,sources,build,covart,verse
from fx import *
PG.configure('/festivals/maha-shivaratri/',[('','Mahāśivarātri','The Great Night of Śiva')],'navy','Mahāśivarātri','Lord','Śivarātri')
PG.CFG.update(backurl='/festivals/',backname='all festivals')
PG.OUT='outd/maha-shivaratri/'
i=0
SH=lambda: shiva()
def pillar_f(): return '<rect x="-14" y="-150" width="28" height="150" fill="#ff8c1a"/><path d="M-14 -150 q14 -20 28 0" fill="#ffd60a"/>'+''.join(f'<path d="M-14 -{k*30+10} q-10 -10 0 -20 M14 -{k*30+20} q10 -10 0 -20" fill="#ffd60a" stroke="#e0501a"/>' for k in range(5))
def boar(): return beast('boar','#6a5a4a') if False else '<ellipse rx="26" ry="14" cy="-14" fill="#6a5a4a"/><path d="M24 -18 l10 4 l-10 4" fill="#6a5a4a"/><path d="M-16 0 v-4 M16 0 v-4" stroke-width="4"/>'
def swan(): return '<path d="M-20 0 q0 -16 20 -14 q14 0 18 -10 q2 -14 -8 -14 q8 -8 12 2 q4 16 -10 26 q-10 10 -32 10z" fill="#fff"/><path d="M2 -36 l6 -2" stroke="#e0a800" stroke-width="3"/>'
def bilvatree(): return '<path d="M0 0 v-60" stroke="#6a4a2a" stroke-width="8"/>'+''.join(f'<g transform="translate({x} {y})"><path d="M0 0 q-8 -6 -10 -14 q8 2 10 14z M0 0 q8 -6 10 -14 q-8 2 -10 14z M0 0 q0 -10 0 -16" fill="#3a9a4a" stroke="#2f7a3a"/></g>' for x,y in [(-30,-60),(-10,-80),(14,-76),(32,-58),(0,-62),(-20,-44),(22,-42)])
def deer(): return '<ellipse cy="-20" rx="20" ry="10" fill="#c98a5a"/><path d="M-14 -12 v14 M14 -12 v14 M-8 -12 v14 M8 -12 v14" stroke-width="2.5"/><path d="M18 -24 l8 -14 q6 2 4 8 l-6 6z" fill="#c98a5a"/>'
def stag(): return deer()+'<path d="M26 -38 l-4 -10 M26 -38 l6 -10 M26 -38 l12 -4" stroke-width="2"/>'
def hunter(): return person('#6a4a2a')+g(14,-20,.7,bow())
def ketaki(): return '<path d="M0 0 q-6 -20 0 -40 q6 20 0 40z" fill="#f4ecd8"/><path d="M0 -6 q-12 -14 -14 -30 M0 -6 q12 -14 14 -30" stroke="#c9c09a" fill="none"/>'
def mountain_temple(): return mountain('#8a9a8a',True)
NIGHTB=f'<rect width="560" height="190" fill="#20243a"/>'
COV=covart('A Śiva liṅga with bilva leaves and a lamp under a dark sky, with a crescent moon, and a pillar of fire rising behind',f'<rect width="440" height="196" fill="#20243a"/>'+''.join(f'<circle cx="{(37*k)%440}" cy="{(23*k*k)%120+8}" r="1.4" fill="#fff8d0" stroke="none"/>' for k in range(1,22))+g(220,196,.9,pillar_f())+g(220,186,1.6,linga())+g(120,190,1.3,lamp())+g(320,190,1.3,lamp())+g(380,50,1,moon())+g(190,148,.8,'<path d="M0 0 q-8 -6 -10 -14 q8 2 10 14z M0 0 q8 -6 10 -14 q-8 2 -10 14z M0 0 v-16" fill="#3a9a4a" stroke="#2f7a3a"/>'))
pp=[foreword(i,['Every month has a Śivarātri, the fourteenth night of the waning moon. Once a year, at the end of Māgha, it becomes <b>Mahāśivarātri</b>, the great night of Śiva. Devotees fast all day, stay awake all night, and worship the liṅga four times, once in each watch of the night, with water, milk, bilva leaves and the five syllables <b>namaḥ śivāya</b>.','This article tells all the stories of the night in full: the pillar of fire that Brahmā and Viṣṇu could not measure, the hunter who worshipped by accident, the poison held in the throat, and the wedding of Śiva and Pārvatī. It gives the verses sung that night, explains the four watches step by step, and visits Karnataka’s Śiva shrines, from Gōkarṇa to Mysuru’s palace.'],[('z','Why stay awake all night for Śiva?'),('b','Because the night is his, Zappy. And because the stories say even an accidental vigil changed a hunter’s life. Imagine a deliberate one.')]),
 glance([('Name','Mahāśivarātri, “the great night of Śiva”; Śivarātri (Kannada)'),('When','Kṛṣṇa Caturdaśī, the 14th of the waning fortnight, in Māgha (amānta) / Phālguna (pūrṇimānta); February–March'),('Monthly','Every Kṛṣṇa Caturdaśī is a Māsa Śivarātri'),('Practice','Fast, all-night vigil (jāgaraṇa), worship of the liṅga in four watches (yāmas)'),('Offerings','Water, milk, curd, ghee, honey, bilva leaves, bhasma, rudrākṣa, the five syllables'),('Stories','Liṅgodbhava; the hunter Gurudruha; Nīlakaṇṭha; the wedding of Śiva and Pārvatī'),('Texts','Śiva, Liṅga, Skanda and Padma Purāṇas')],svg(560,140,'A liṅga under a night sky with four lamps for the four watches',NIGHTB.replace('190','140')+g(280,130,1.4,linga())+''.join(g(x,130,1.2,lamp()) for x in (90,170,390,470))+g(480,30,.8,moon()))),
 reading('night','THE NIGHT AND THE DATE','Caturdaśī of the dark fortnight',svg(560,160,'The waning moon shrinking night by night to a thin sliver on the fourteenth',NIGHTB.replace('190','160')+''.join(f'<circle cx="{60+k*90}" cy="70" r="20" fill="#fff8d0" stroke="none"/><circle cx="{60+k*90+8+k*6}" cy="70" r="20" fill="#20243a" stroke="none"/>' for k in range(5))+lab(420,115,'14th: Śivarātri').replace('#111','#fff8d0')),['<b>A monthly night.</b> Every lunar month, the fourteenth night of the waning moon (<b>Kṛṣṇa Caturdaśī</b>), the night before the new moon, is a Śivarātri; many devotees keep it every month as <b>Māsa Śivarātri</b>, with the '+L('/festivals/pradosha/','Pradoṣa')+' the evening before.','<b>The great one.</b> The Śivarātri of Māgha (in the amānta calendar used in Karnataka; Phālguna in the north’s reckoning) is <b>Mahāśivarātri</b>, the most important night of the Śaiva year. It falls in February or March, at the end of winter.','<b>The midnight rule.</b> The day chosen is the one on which Caturdaśī prevails at midnight (<i>niśītha</i>), because the worship centres on the middle of the night. Almanacs settle the rare years when this is in doubt.','<b>Night, not day.</b> Unlike most festivals, which happen by day, Śivarātri’s heart is darkness: the moon almost gone, lamps lit, the temple open all night.'],[('z','So there are twelve Śivarātris a year?'),('b','Twelve small ones and one great one, Zappy. The great one is where everyone stays up.')],'The moon nearly gone, <b>Śiva’s night</b>.'),
 story('lingodbhava','THE PILLAR OF FIRE','Liṅgodbhava',strip('Three panels: Brahmā and Viṣṇu arguing; a pillar of fire appearing between them, Brahmā as a swan flying up and Viṣṇu as a boar digging down; Śiva emerging from the pillar',[panel([(god('#c0392b'),1),(vishnu(),.8)],'#e9e3f5',150),panel([(pillar_f(),.9),(swan(),.8),(boar(),.7)],'#20243a',None),panel([(pillar_f(),.8),(SH(),.9)],'#fde9c8',150)],['who is greater?','up and down','Śiva appears']),'Told in the Śiva Purāṇa (Vidyeśvara Saṃhitā) and the Liṅga Purāṇa.',['<b>Brahmā</b> and <b>Viṣṇu</b> once quarrelled over which of them was the greater, and their quarrel grew into a battle that shook the worlds.','Between them appeared a column of fire with no visible top and no visible bottom. A voice said: whoever finds its end is the greater.','Brahmā took the form of a <b>swan</b> and flew upward; Viṣṇu took the form of a <b>boar</b> and dug downward. For ages they went on and found no end.','Viṣṇu came back and admitted it. Brahmā came back with a <b>ketakī flower</b> that had been falling from the top, and lied that he had seen the summit, with the flower as his witness.','Śiva stepped out of the pillar. He honoured Viṣṇu’s truthfulness and rebuked Brahmā; the flower, for its false witness, was barred from his worship ever after. The pillar of fire is the first <b>liṅga</b>, and Śiva Purāṇa tradition places its appearance on this night.'],[('z','So that’s why ketakī isn’t offered to Śiva?'),('b','Because it lied, Zappy. Every Śiva temple remembers its false witness.')],'The endless <b>beyond all measure</b>.'),
 verse('v-linga','Liṅgāṣṭakam, verse 1','The liṅga worshipped by Brahmā and Viṣṇu',['brahmamurāri surārcita liṅgaṃ','nirmalabhāsita śobhita liṅgam','janmaja duḥkha vināśaka liṅgaṃ','tat praṇamāmi sadāśiva liṅgam'],svg(200,150,'A liṅga glowing with light between a swan and a boar',f'<rect width="200" height="150" fill="#20243a"/>'+g(100,140,1.3,linga())+'<circle cx="100" cy="88" r="40" fill="#ffd60a" opacity=".15" stroke="none"/>'+g(36,60,.7,swan())+g(164,140,.7,boar())),'The liṅga worshipped by Brahmā, by Viṣṇu (Murāri) and by the gods; the liṅga radiant with pure light; the liṅga that destroys the sorrow born of birth: to that liṅga of the ever-auspicious Śiva I bow.',[('brahma-murāri','Brahmā and Viṣṇu'),('sura-arcita','worshipped by the gods'),('nirmala-bhāsita','shining with pure light'),('janmaja-duḥkha','sorrow born of birth'),('vināśaka','destroying'),('praṇamāmi','I bow')],'<b>The pillar in the first line.</b> The Liṅgāṣṭakam, sung in Śiva temples across Karnataka, opens with the Liṅgodbhava story: the liṅga is the one Brahmā and Viṣṇu could not measure and so worshipped. On Śivarātri it is sung at every watch.',k='The liṅga that <b>ends sorrow</b>.',note='Text as on our '+L('/shiva/lingashtakam/','Liṅgāṣṭakam')+' page.'),
 story('hunter1','THE HUNTER IN THE BILVA TREE','Gurudruha’s night, part one',strip('Three panels: the hungry hunter leaving home; climbing a bilva tree beside a pond with a liṅga beneath; a doe coming to drink',[panel([(hunter(),1.1),(person('#8a6a4a'),.9)],'#e9d6c0',150),panel([(bilvatree(),1.2),(linga(),.6)],'#20243a',150),panel([(deer(),1.2),(river(144,140,'#3a5a8a'),1)],'#20243a',None)],['a hungry family','up the bilva tree','the first deer']),'The Śiva Purāṇa, Koṭirudra Saṃhitā, chapter 40, tells this as the story of the first Śivarātri vow, kept without knowing it.',['<b>Gurudruha</b>, a hunter of the forest, cruel by trade, found nothing to kill all day, and his family at home was starving. That day happened to be Śivarātri.','At dusk he took a vessel of water and climbed a <b>bilva tree</b> beside a pond, to wait for animals coming to drink. Under the tree, unseen, stood a Śiva liṅga.','In the first watch of the night a doe came to drink. As he drew his bow, the tree shook: a few bilva leaves and drops of water from his vessel fell on the liṅga. Without knowing it, he had worshipped Śiva.','The doe saw him and begged: let me take my young ones to their father first; I promise to come back. Moved, he let her go.','So the first watch passed: no food, no sleep, a little water and a few leaves on the liṅga.'],[('z','He didn’t even know the liṅga was there?'),('b','Not a clue, Zappy. Keep reading: the night isn’t over.')],'Worship <b>without knowing</b>.'),
 story('hunter2','FOUR WATCHES, FOUR MERCIES','Gurudruha’s night, part two',strip('Three panels: another doe and a stag come and are let go; at dawn the whole deer family returns to be killed; Śiva appears to the hunter',[panel([(deer(),1),(stag(),1)],'#20243a',None),panel([(stag(),.9),(deer(),.9),(deer(),.6)],'#fde9c8',150),panel([(SH(),1),(hunter(),.9)],'#fff3cf',150)],['more deer, more promises','they all come back','Śiva appears']),'The rest of the night, as the Śiva Purāṇa tells it.',['In the second watch another doe came; again the tree shook, leaves and water fell on the liṅga, and again she pleaded to go home first and promised to return. He let her go.','In the third watch a <b>stag</b> came and asked the same. Every watch, the hunter stayed awake, fasting, and every watch the liṅga received water and bilva.','At dawn the whole deer family came back together, each insisting on being killed first so the others could live, true to their word.','Seeing such truthfulness in animals, the hunter’s heart broke open. He lowered his bow and said: go in peace.','Śiva appeared before him, pleased with the vow he had kept without knowing: fasting, wakefulness, worship in four watches. The hunter was freed; the deer too were released from their animal births. Śiva, the text says, stayed on Mount Arbuda as <b>Vyādheśvara</b>, Lord of the Hunter.'],[('z','So the deer taught the hunter?'),('b','Truthfulness taught him, Zappy, and the night did the rest. That’s why the vigil and the four pūjās matter.')],'A night that <b>changed a hunter</b>.'),
 verse('v-bilva','Bilvāṣṭakam, verse 1','Offering a single bilva leaf',['tridalaṃ triguṇākāraṃ trinetraṃ ca triyāyudham','trijanmapāpasaṃhāram ekabilvaṃ śivārpaṇam'],svg(200,150,'A single three-part bilva leaf offered on a liṅga',f'<rect width="200" height="150" fill="#fffaf0"/>'+g(100,140,1.3,linga())+g(100,62,2.2,'<path d="M0 0 q-8 -6 -10 -14 q8 2 10 14z M0 0 q8 -6 10 -14 q-8 2 -10 14z M0 0 q-2 -10 0 -18 q2 8 0 18z" fill="#3a9a4a" stroke="#2f7a3a"/>')),'Three-leaved, shaped like the three guṇas, like the three eyes and the three weapons, destroying the sins of three births: one bilva leaf, offered to Śiva.',[('tri-dalam','three-leaved'),('tri-guṇa-ākāram','shaped like the three qualities'),('tri-netram','three-eyed'),('tri-āyudham','the three-pronged weapon'),('trijanma-pāpa','sins of three births'),('śiva-arpaṇam','offered to Śiva')],'<b>Why bilva.</b> The three-part leaf of the bilva (bael) tree is Śiva’s favourite offering, as the hunter’s story shows. It is offered whole, unbroken, stalk toward the devotee, often with “namaḥ śivāya”. On Śivarātri temples receive bilva by the sackful.',k='One leaf, <b>whole and sincere</b>.',note='Text as on our '+L('/shiva/bilvashtakam/','Bilvāṣṭakam')+' page.'),
 story('wedding','THE WEDDING OF ŚIVA AND PĀRVATĪ','Many celebrate the night as their wedding',strip('Three panels: Pārvatī in penance in the snow; Śiva arriving with his wild wedding party on Nandi; the wedding with Viṣṇu giving away the bride',[panel([(devi(items=('rosary',)),1)],'#e3eaf3',150),panel([(nandi(),.8),(SH(),.7)],'#fde9c8',150),panel([(SH(),.8),(devi(items=('lotus',)),.8),(vishnu(),.6)],'#fff3cf',150)],['Pārvatī’s tapas','the wedding party','the marriage']),'From the Śiva Purāṇa (Rudra Saṃhitā, Pārvatī Khaṇḍa) and Kālidāsa’s Kumārasambhava; the link to this night is a widely held tradition.',['After Satī’s death Śiva withdrew into meditation. She was reborn as <b>Pārvatī</b>, daughter of the mountain king Himavān.','When even Kāma’s arrow failed (read our '+L('/festivals/holi/','Holi article')+'), Pārvatī undertook fierce penance in the snows, eating at last not even leaves: hence the name <b>Aparṇā</b>.','Śiva tested her in disguise, mocking himself; she would hear nothing against him. Pleased, he agreed to marry her.','He came to Himavān’s city with the strangest wedding party ever seen: ghosts and goblins, snakes for ornaments, ash for perfume, riding Nandi. Pārvatī’s mother fainted; then Śiva showed his beautiful form.','The wedding was performed with Viṣṇu giving away the bride, many say, and the gods in attendance. Many devotees, especially in the north, keep Śivarātri as the night of this marriage.'],[('z','Ghosts at a wedding?'),('b','Śiva’s friends, Zappy. He refuses no one. The wedding party is the whole point.')],'The ascetic <b>becomes a householder</b>.'),
 reading('nilakantha','THE POISON HELD IN THE THROAT','Nīlakaṇṭha, and the night of waiting',svg(560,160,'Śiva holding dark poison in his throat with gods watching at night',NIGHTB.replace('190','160')+g(280,150,1.4,SH().replace('#9fb7d6','#4a6aa6'))+''.join(g(x,150,.8,god(c)) for x,c in [(110,'#1d6fb8'),(170,'#c0392b'),(390,'#e0a800'),(450,'#2a9d6f')])),['<b>The story.</b> When the gods and demons churned the ocean of milk, the first thing to rise was the poison <b>hālāhala</b>. Śiva drank it to save the worlds, and Pārvatī held his throat so it would not go down: it stayed there, turning his throat blue. (The whole story is in our '+L('/festivals/pradosha/nilakantha/','Nīlakaṇṭha article')+'.)','<b>The vigil link.</b> One widely told tradition says the gods kept awake all night beside Śiva after he drank the poison, singing and dancing to keep him from sleep, and that this night was Śivarātri. The Purāṇas more often tie the poison to the Pradoṣa hour; the tradition is popular rather than textual.','<b>Why it fits.</b> Śivarātri is a night of staying awake for someone’s sake. Many teachers read Nīlakaṇṭha as the model of the night: hold what hurts without swallowing it or spitting it out. (Interpretation.)','<b>Abhiṣeka.</b> The constant pouring of water and milk on the liṅga is often explained as cooling the one who holds the poison.'],[('z','So the vigil is to keep Śiva company?'),('b','That’s one beautiful reading, Zappy. The gods stayed up for him; we stay up for him.')],'Hold the poison, <b>keep the vigil</b>.'),
 cards('four','THE FOUR WATCHES','How the night is kept',svg(560,120,'Four segments of night, each with a liṅga and a different offering',NIGHTB.replace('190','120')+''.join(g(70+k*140,100,1,linga())+lab(70+k*140,30,t).replace('#111','#fff8d0') for k,t in enumerate(['1st yāma: milk','2nd: curd','3rd: ghee','4th: honey']))),[('🌙','The fast','From the morning of Caturdaśī; strict keepers take nothing, others fruit and milk. It is broken next morning after the final worship and a meal for others.'),('🕯️','Four yāmas','The night is divided into four watches of about three hours. In each, the liṅga is bathed (traditionally with milk, curd, ghee and honey in turn, then water), dressed with sandal and bilva, and worshipped with lamps.'),('🔤','The mantra','“<b>Namaḥ śivāya</b>” (the pañcākṣara) is repeated through the night; many chant the Śrī Rudram and Camakam, or the '+L('/shiva/mahamrityunjaya-mantra/','Mahāmṛtyuñjaya')+'.'),('👁️','Jāgaraṇa','Staying awake with bhajans, stories, temple visits and readings. In many Karnataka towns temples stay open all night and bhajan groups sing till dawn.')],[('z','Can I keep a shorter version?'),('b','Of course, Zappy. One pūjā at night, the five syllables, a little fasting, a little waking. Sincerity counts more than hours.')],'Four watches, <b>one name</b>.'),
 verse('v-panchakshara','Śiva Pañcākṣara Stotram, verse 1','Na: the first of the five syllables',['nāgendrahārāya trilocanāya','bhasmāṅgarāgāya maheśvarāya','nityāya śuddhāya digambarāya','tasmai nakārāya namaḥ śivāya'],svg(200,150,'Śiva with a serpent garland, three eyes and ash on his body',f'<rect width="200" height="150" fill="#e3eaf3"/>'+g(100,140,1.3,SH())+'<path d="M80 92 q20 14 40 0" stroke="#2a6a3a" stroke-width="4" fill="none"/>'),'To him who wears the king of serpents as a garland, the three-eyed, whose body is smeared with ash, the great lord, eternal, pure, clothed in the directions: to him who is the syllable “na”, salutations to Śiva.',[('nāgendra-hārāya','garlanded with the serpent king'),('tri-locanāya','three-eyed'),('bhasma-aṅgarāgāya','smeared with ash'),('nityāya','eternal'),('digambarāya','clad in the directions'),('na-kārāya','who is the syllable “na”')],'<b>Five syllables, five verses.</b> The Pañcākṣara Stotram, attributed to Śaṅkara, gives one verse to each syllable of <b>na-maḥ-śi-vā-ya</b>. It is the simplest hymn to keep through the night: one verse per syllable, and the mantra itself in between.',k='<b>Na-maḥ-śi-vā-ya</b>, five syllables.',note='Text as on our '+L('/shiva/shiva-panchakshara-stotram/','Śiva Pañcākṣara Stotram')+' page, where all five verses are given.'),
 story('gokarna','GŌKARṆA AND THE ĀTMALIṄGA','Karnataka’s great Śivarātri shrine',strip('Three panels: Rāvaṇa receiving a liṅga from Śiva; a cowherd boy holding it at the seashore; the liṅga fixed in the ground while Rāvaṇa pulls',[panel([(SH(),.9),(demon('#7a1d12'),.9)],'#e3eaf3',150),panel([(ganesha(seat=False),.6),(linga(),.5)],'#dfe9f6',150),panel([(demon('#7a1d12'),.9),(linga(),.8)],'#e9d6c0',150)],['the gift','the boy at the shore','it will not move']),'The temple legend of Gōkarṇa Mahābaleśvara on the Uttara Kannaḍa coast (sthala-purāṇa; tellings differ).',['<b>Rāvaṇa</b>, by his penance, won from Śiva the <b>Ātmaliṅga</b>, Śiva’s own self in a liṅga, on condition that wherever it was first set on the ground, there it would stay.','The gods feared Laṅkā would become invincible. Viṣṇu dimmed the sun so that it seemed evening, and Rāvaṇa, a strict keeper of rites, had to stop for his twilight prayers at Gōkarṇa.','<b>Gaṇeśa</b>, disguised as a cowherd boy, offered to hold the liṅga while he prayed, saying he would call three times and then set it down.','Gaṇeśa called three times quickly and placed it on the ground. Rāvaṇa pulled with all his might; the liṅga would not move, only stretch like a cow’s ear: <b>Gō-karṇa</b>. He named it <b>Mahābala</b>, the mighty one.','Gōkarṇa draws huge crowds on Śivarātri, with a chariot festival and a sea bath; pieces Rāvaṇa flung away are said to rest at Murudeśvara and other coastal shrines.'],[('z','Gaṇeśa tricked Rāvaṇa?'),('b','With three quick calls, Zappy. And the cow’s ear gave the place its name.')],'The liṅga that <b>would not move</b>.'),
 cards('karnataka','ŚIVARĀTRI IN KARNATAKA','From the coast to the palace',fig_row('A coastal temple, a hill, a palace and a liṅga',[(gopuram() if False else palace(),.8),(mountain(),.8),(linga(),1.4),(nandi(),.9)],['Mysuru','MM Hills','liṅga','Nandi'],gy=150),[('👑','Mysuru','At the <b>Trinayaneśvara</b> temple inside the palace fort, the deity is worshipped through the night, and the gold mask (kavaca) presented by the royal family is placed on the liṅga for Śivarātri. Read our '+L('/temples-of-india/around-mysuru/palace-temples/','palace temples')+' guide.'),('⛰️','Male Mahadēśvara','The hill shrine of the saint Mādappa holds one of its great fairs on Śivarātri, with pilgrims walking up from Karnataka and Tamil Nadu. See '+L('/temples-of-india/around-mysuru/mm-hills/','MM Hills')+'.'),('🌊','The coast','<b>Gōkarṇa</b>’s chariot festival and sea bath; <b>Murudeśvara</b> by the sea; Dharmasthaḷa’s Mañjunātha with its night-long padayātrā.'),('🏛️','Old Mysore','<b>Nañjanagūḍu</b>, <b>Gavi Gaṅgādhareśvara</b> in Bengaluru, Śivagaṅge and countless village temples keep night-long bhajans; Kannada vacana songs of the Śivaśaraṇas fill the night.')],[('z','Where would you go?'),('b','Wherever the bhajans are, Zappy. The best Śivarātri is the one you stay awake for.')],'A whole state <b>stays awake</b>.'),
 reading('meaning','WHAT ŚIVARĀTRI MEANS','The night that wakes you up',svg(560,150,'A single lamp burning in a dark room beside a meditating figure',NIGHTB.replace('190','150')+g(200,130,1.2,sage('#ff8c1a'))+g(330,128,2,lamp())+'<circle cx="330" cy="100" r="60" fill="#ffd60a" opacity=".1" stroke="none"/>'),['<b>Waking.</b> Śiva is called the one who is always awake. The vigil asks us to be awake for one night in the year as he is always: not just without sleep, but attentive. (Interpretation.)','<b>The night.</b> Śiva is worshipped in darkness: the moon almost gone, the world asleep. Many teachers read the night as the dark of ignorance, and the lamp and the mantra as the light that can still be kept burning in it.','<b>No one shut out.</b> The hunter knew nothing and still was received; the wedding party was made of ghosts. Śivarātri is the most open of festivals: the simplest leaf, given wholeheartedly, is enough.','<b>Truthfulness.</b> Brahmā’s lie was rebuked, Viṣṇu’s honesty honoured; the deer’s promises won the hunter’s freedom. The night’s stories praise truth above all.'],[('z','If I could do one thing for Śivarātri?'),('b','Stay awake one watch, Zappy: three hours with the lamp lit, a bilva leaf, and namaḥ śivāya. Then tell someone the hunter’s story.')],'Be awake, <b>be truthful</b>.'),
 end(i,['<b>When.</b> Kṛṣṇa Caturdaśī of Māgha, the night before the new moon.','<b>Keep.</b> Fast, stay awake, worship in four watches with bilva and namaḥ śivāya.','<b>Liṅgodbhava.</b> The endless pillar; Brahmā’s lie, Viṣṇu’s honesty.','<b>Hunter.</b> Gurudruha’s accidental vigil and the truthful deer.','<b>Karnataka.</b> Gōkarṇa’s Ātmaliṅga, Mysuru’s gold mask, MM Hills.'],'Previous: '+L('/festivals/ratha-saptami/','Ratha Saptamī')+'. Next: '+L('/festivals/holi/','Holi and Kāmana habba')+'.','Mahāśivarātri: the great night of Śiva'),
 sources([('Stories:','Śiva Purāṇa, Vidyeśvara Saṃhitā (Liṅgodbhava, the ketakī) and Koṭirudra Saṃhitā ch. 40 (the hunter Gurudruha; via vedapath.app, wisdomlib.org, hindutone.com); Rudra Saṃhitā, Pārvatī Khaṇḍa (the wedding); Bhāgavata 8.7 (the poison). Gōkarṇa temple legend.'),('Practice and dates:','Wikipedia, “Maha Shivaratri” (Kṛṣṇa Caturdaśī, four watches, bilva, regional observances, dance festivals). Verses from our own Liṅgāṣṭakam, Bilvāṣṭakam and Pañcākṣara pages.')],'the tie of the poison story and of the wedding to this night (popular tradition); the order of abhiṣeka substances by watch (varies); Gōkarṇa legend details (sthala-purāṇa, tellings differ); the Trinayaneśvara gold mask and Śivarātri customs at individual temples (as reported; practice may change).','Interpretations are marked as such.')]
build(i,'THE NIGHT OF ŚIVA · FOUR WATCHES · THE PILLAR OF FIRE',COV,'Bilva, lamp and liṅga','The <b>night</b> and its date, all the <b>stories</b> told in full (the pillar of fire, the hunter, the poison, the wedding), the <b>verses</b>, the four watches, and <b>Karnataka</b> from Gōkarṇa to Mysuru.','Mahāśivarātri explained: Kṛṣṇa Caturdaśī, Liṅgodbhava and the ketakī, the hunter Gurudruha from the Śiva Purāṇa, Nīlakaṇṭha, the wedding of Śiva and Pārvatī, the four yāmas, Liṅgāṣṭakam, Bilvāṣṭakam and Pañcākṣara verses, Gōkarṇa’s Ātmaliṅga and Śivarātri in Mysuru.',pp)
print('shivaratri ok',len(pp)+2)
